datasource db {
  provider = "postgresql"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model Sample {
  id             Int      @id @default(autoincrement())
  metric         String
  value          Float
  recordedAt     DateTime
  idempotencyKey String   @unique
  ingestedAt     DateTime @default(now())
}

model RollupResult {
  id        Int      @id @default(autoincrement())
  metric    String   @unique
  count     Int
  p95       Float?
  avg       Float?
  delta     Float?
  updatedAt DateTime
}

import { app, page, route, api, job } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { ingestSample, enqueueRollup, getDashboard } from "./src/apis" with { type: "ref" };
import { rollupMetrics } from "./src/jobs" with { type: "ref" };

export default app({
  name: "waspmetrics",
  wasp: { version: "^0.25.0" },
  title: "waspmetrics",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  spec: [
    route("RootRoute", "/", page(MainPage)),
    api("POST", "/api/samples", ingestSample, { entities: ["Sample"], auth: false }),
    api("POST", "/api/rollup", enqueueRollup, { auth: false }),
    api("GET", "/api/dashboard", getDashboard, { entities: ["RollupResult"], auth: false }),
    job(rollupMetrics, {
      executor: "PgBoss",
      entities: ["Sample", "RollupResult"],
      schedule: {
        cron: "23 3 * * *",
        args: { reason: "cron" }
      }
    })
  ],
});

function roundHalfAwayFromZero(num: number, decimals: number): number {
  const factor = Math.pow(10, decimals);
  const sign = Math.sign(num);
  const absoluteValue = Math.abs(num);
  const shifted = absoluteValue * factor;
  const rounded = Math.round(Number((shifted).toFixed(12)));
  return (sign * rounded) / factor;
}

export async function rollupMetrics(args: { reason?: string }, context: any) {
  console.log(`Running rollupMetrics. Reason: ${args?.reason || 'unknown'}`);
  const { Sample, RollupResult } = context.entities;
  const registeredMetrics = ['error_rate', 'latency_ms', 'queue_depth'];
  const now = new Date();

  for (const metric of registeredMetrics) {
    // 1. Find the latest sample's recordedAt for this metric
    const latestSample = await Sample.findFirst({
      where: { metric },
      orderBy: { recordedAt: 'desc' }
    });

    if (!latestSample) {
      // No stored samples at all: persist count 0 and nulls
      await RollupResult.upsert({
        where: { metric },
        create: {
          metric,
          count: 0,
          p95: null,
          avg: null,
          delta: null,
          updatedAt: now
        },
        update: {
          count: 0,
          p95: null,
          avg: null,
          delta: null,
          updatedAt: now
        }
      });
      continue;
    }

    const T = latestSample.recordedAt;
    const currentWindowStart = new Date(T.getTime() - 3600 * 1000);
    const currentWindowEnd = T;
    const previousWindowStart = new Date(T.getTime() - 7200 * 1000);
    const previousWindowEnd = currentWindowStart;

    // Fetch current window samples sorted ascending by value
    const currentSamples = await Sample.findMany({
      where: {
        metric,
        recordedAt: {
          gt: currentWindowStart,
          lte: currentWindowEnd
        }
      },
      orderBy: { value: 'asc' }
    });

    // Fetch previous window samples sorted ascending by value
    const previousSamples = await Sample.findMany({
      where: {
        metric,
        recordedAt: {
          gt: previousWindowStart,
          lte: previousWindowEnd
        }
      },
      orderBy: { value: 'asc' }
    });

    const count = currentSamples.length;
    let avg: number | null = null;
    let p95: number | null = null;
    let delta: number | null = null;

    if (count > 0) {
      const sum = currentSamples.reduce((acc: number, s: any) => acc + s.value, 0);
      avg = roundHalfAwayFromZero(sum / count, 3);

      const p95Index = Math.ceil(0.95 * count) - 1;
      p95 = currentSamples[p95Index].value;

      const prevCount = previousSamples.length;
      if (prevCount > 0) {
        const prevP95Index = Math.ceil(0.95 * prevCount) - 1;
        const prevP95 = previousSamples[prevP95Index].value;
        delta = roundHalfAwayFromZero(p95 - prevP95, 3);
      }
    }

    await RollupResult.upsert({
      where: { metric },
      create: {
        metric,
        count,
        p95,
        avg,
        delta,
        updatedAt: now
      },
      update: {
        count,
        p95,
        avg,
        delta,
        updatedAt: now
      }
    });
  }
}

import { rollupMetrics } from "wasp/server/jobs";

export const ingestSample = async (req: any, res: any, context: any) => {
  const idempotencyKey = req.get('Idempotency-Key');
  if (!idempotencyKey || idempotencyKey.trim() === '') {
    return res.status(400).json({ error: 'Idempotency-Key header is missing or empty' });
  }

  const { metric, value, recordedAt } = req.body;

  const registeredMetrics = ['error_rate', 'latency_ms', 'queue_depth'];
  if (!metric || typeof metric !== 'string' || !registeredMetrics.includes(metric)) {
    return res.status(400).json({ error: 'Invalid or missing metric' });
  }

  if (value === undefined || value === null || typeof value !== 'number' || !Number.isFinite(value)) {
    return res.status(400).json({ error: 'Invalid or missing value' });
  }

  if (!recordedAt || typeof recordedAt !== 'string') {
    return res.status(400).json({ error: 'recordedAt is missing or invalid' });
  }
  const parsedDate = Date.parse(recordedAt);
  if (isNaN(parsedDate)) {
    return res.status(400).json({ error: 'recordedAt is not a valid ISO-8601 timestamp' });
  }

  const { Sample } = context.entities;

  // 1. Check if idempotency key already exists
  const existing = await Sample.findUnique({
    where: { idempotencyKey }
  });

  if (existing) {
    return res.status(200).json({ id: existing.id, duplicate: true });
  }

  // 2. Try to create the sample
  try {
    const sample = await Sample.create({
      data: {
        metric,
        value,
        recordedAt: new Date(recordedAt),
        idempotencyKey
      }
    });
    return res.status(201).json({ id: sample.id, duplicate: false });
  } catch (error: any) {
    // Check if it's a unique constraint violation (P2002 in Prisma)
    if (error.code === 'P2002') {
      const concurrentExisting = await Sample.findUnique({
        where: { idempotencyKey }
      });
      if (concurrentExisting) {
        return res.status(200).json({ id: concurrentExisting.id, duplicate: true });
      }
    }
    throw error;
  }
};

export const enqueueRollup = async (req: any, res: any, context: any) => {
  try {
    const submittedJob = await rollupMetrics.submit({ reason: "manual" });
    return res.status(202).json({
      jobId: submittedJob.jobId,
      jobName: "rollupMetrics"
    });
  } catch (error: any) {
    return res.status(500).json({ error: error.message });
  }
};

export const getDashboard = async (req: any, res: any, context: any) => {
  const { RollupResult } = context.entities;
  const registeredMetrics = ['error_rate', 'latency_ms', 'queue_depth'];

  try {
    // Fetch all RollupResults
    const results = await RollupResult.findMany({
      where: {
        metric: { in: registeredMetrics }
      }
    });

    const resultsMap = new Map(results.map((r: any) => [r.metric, r]));

    const response = registeredMetrics.map((metric) => {
      const existing = resultsMap.get(metric);
      if (existing) {
        return {
          metric: existing.metric,
          count: existing.count,
          p95: existing.p95,
          avg: existing.avg,
          delta: existing.delta,
          updatedAt: existing.updatedAt.toISOString()
        };
      } else {
        return {
          metric,
          count: 0,
          p95: null,
          avg: null,
          delta: null,
          updatedAt: null
        };
      }
    });

    // Sort by metric ascending
    response.sort((a, b) => a.metric.localeCompare(b.metric));

    return res.status(200).json(response);
  } catch (error: any) {
    return res.status(500).json({ error: error.message });
  }
};

